UPDATE behavior_event_outbox SET status=CASE WHEN attempts >= #{maxAttempts} OR #{error}='INVALID_EVENT' THEN 'DEAD' ELSE 'READY' END,
    available_at=clock_timestamp()+(#{delayMs} * interval '1 millisecond'),last_error=#{error}
WHERE event_id=#{eventId} AND fence=#{fence} AND status='SENDING' AND available_at > clock_timestamp()
